// Nodo Code (n8n)
// 1. Filtra los items cuya "Fecha y Hora" cae dentro de la última semana.
// 2. Unifica los objetos filtrados en un solo texto para el nodo Message-a-Model.

const now = new Date();
const oneWeekAgo = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000);

function parseFechaHora(fechaHoraRaw) {
  if (!fechaHoraRaw || typeof fechaHoraRaw !== 'string') return null;

  const parts = fechaHoraRaw.split(',');
  if (parts.length === 0) return null;

  const fechaPart = parts[0].trim();
  const horaPart = (parts.slice(1).join(',') || '').trim();

  const fechaTokens = fechaPart.split('/').map(t => t.trim());
  if (fechaTokens.length !== 3) return null;
  const dia = parseInt(fechaTokens[0], 10);
  const mes = parseInt(fechaTokens[1], 10) - 1;
  const anio = parseInt(fechaTokens[2], 10);
  if (Number.isNaN(dia) || Number.isNaN(mes) || Number.isNaN(anio)) return null;

  let horaStr = horaPart.replace(/\s+/g, ' ').trim();
  horaStr = horaStr.replace(/a\.?\s?m\.?/ig, 'AM');
  horaStr = horaStr.replace(/p\.?\s?m\.?/ig, 'PM');

  const ampmMatch = horaStr.match(/\b(AM|PM)\b/i);
  const ampm = ampmMatch ? ampmMatch[1].toUpperCase() : null;
  const timeOnly = horaStr.replace(/\b(AM|PM)\b/i, '').trim();

  const timeTokens = timeOnly.split(':').map(t => t.trim()).filter(t => t !== '');
  let hh = 0, mm = 0, ss = 0;
  if (timeTokens.length >= 1) hh = parseInt(timeTokens[0], 10) || 0;
  if (timeTokens.length >= 2) mm = parseInt(timeTokens[1], 10) || 0;
  if (timeTokens.length >= 3) ss = parseInt(timeTokens[2], 10) || 0;

  if (ampm) {
    if (ampm === 'AM' && hh === 12) hh = 0;
    if (ampm === 'PM' && hh < 12) hh += 12;
  }

  return new Date(anio, mes, dia, hh, mm, ss);
}

// Validar input
if (!Array.isArray(items)) return [];

// Filtrar items dentro de la última semana
const filteredItems = items.filter(it => {
  const raw = it?.json?.["Fecha y Hora"];
  const fecha = parseFechaHora(raw);
  if (!fecha || Number.isNaN(fecha.getTime())) return false;
  return fecha >= oneWeekAgo && fecha <= now;
});

// Si no hay resultados, devolver un mensaje indicando eso
if (filteredItems.length === 0) {
  return [{ json: { message: "No se encontraron mensajes en la última semana." } }];
}

// Construir mensaje unificado
const combinedText = filteredItems.map(it => {
  const id = it.json.Id || 'Sin ID';
  const fecha = it.json["Fecha y Hora"] || 'Sin fecha';
  const msg = it.json.Mensaje || 'Sin mensaje';
  return `🕒 ${fecha}\n🆔 ${id}\n💬 ${msg}`;
}).join('\n\n---\n\n');

// Devolver un único objeto con el texto concatenado
return [
  {
    json: {
      message: `Análisis de mensajes de la última semana:\n\n${combinedText}`
    }
  }
];
